import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel 6353c49:
# &packet.PlaySound{SoundName: "note.harp", Position: mgl32.Vec3{1, 2, 3}, Volume: 0.5, Pitch: 1.5,
#     Handle: protocol.Option(uint64(42))}
V1001_WITH_HANDLE = bytes.fromhex("096e6f74652e686172701020300000003f0000c03f012a00000000000000")

# generated by gophertunnel 6353c49:
# &packet.PlaySound{SoundName: "note.harp", Position: mgl32.Vec3{1, 2, 3}, Volume: 0.5, Pitch: 1.5}
V1001_WITHOUT_HANDLE = bytes.fromhex("096e6f74652e686172701020300000003f0000c03f00")

# generated by gophertunnel b8bd735:
# &packet.PlaySound{SoundName: "note.harp", Position: mgl32.Vec3{1, 2, 3}, Volume: 0.5, Pitch: 1.5,
#     LoopCount: 3, Handle: protocol.Option(uint64(42))}
V2168_WITH_HANDLE = bytes.fromhex("096e6f74652e686172701020300000003f0000c03f06012a00000000000000")

GOLDENS = [
    pytest.param(
        v1001.PlaySoundPacket(
            name="note.harp",
            pos=v1001.BlockPos(x=8, y=16, z=24),
            volume=0.5,
            pitch=1.5,
            server_sound_handle=v1001.ServerSoundHandle(value=42),
        ),
        V1001_WITH_HANDLE,
        id="v1001-with-handle",
    ),
    pytest.param(
        v1001.PlaySoundPacket(name="note.harp", pos=v1001.BlockPos(x=8, y=16, z=24), volume=0.5, pitch=1.5),
        V1001_WITHOUT_HANDLE,
        id="v1001-without-handle",
    ),
    pytest.param(
        v2168.PlaySoundPacket(
            name="note.harp",
            pos=v2168.BlockPos(x=8, y=16, z=24),
            volume=0.5,
            pitch=1.5,
            loop_count=3,
            server_sound_handle=v2168.ServerSoundHandle(value=42),
        ),
        V2168_WITH_HANDLE,
        id="v2168-with-handle",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_play_sound_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_play_sound_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_a_v1001_play_sound_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.PlaySoundPacket.from_bytes(V1001_WITH_HANDLE)


def test_a_v2168_play_sound_body_leaves_bytes_over_as_a_v1001_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.PlaySoundPacket.from_bytes(V2168_WITH_HANDLE)
